package top.monitorglobal.tv;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class TargetAlertTest {
 final long now=1800000000000L;final Map<String,Boolean> health=Map.of("USGS",true);
 Alert quake(String id,double mag,String version){Alert a=new Alert(id,"earthquake",version,"M5,4 · Nepal","","earthquake",now,now-1000,mag>=6);a.provider="USGS";a.catalog="USGS";a.magnitude=mag;a.depth=12;a.targetArea=mag<6?"Katmandu · Nepal":"";return a;}
 List<Alert> accept(AlertTracker t,Alert a,long time,boolean enabled){return t.accept(List.of(a),true,true,time,health,enabled);}
 @Test public void baselineIsSilentAndM5UsesSmallCardWithoutChangingMainThreshold(){AlertTracker t=new AlertTracker();assertTrue(accept(t,quake("old",5.4,"v1"),now,true).isEmpty());List<Alert> out=accept(t,quake("new",5.4,"v1"),now+1000,true);assertEquals(1,out.size());assertTrue(out.get(0).compact);assertFalse(t.seen.get("new").tracked);assertTrue(accept(t,quake("new",5.4,"v1"),now+2000,true).isEmpty());}
 @Test public void upgradeFromCompactToM6UsesPrimaryBannerAndTracksLaterDownwardRevision(){AlertTracker t=new AlertTracker();t.accept(List.of(),true,true,now,health,true);assertTrue(accept(t,quake("x",5.9,"v1"),now+1000,true).get(0).compact);Alert upgrade=accept(t,quake("x",6,"v2"),now+2000,true).get(0);assertFalse(upgrade.compact);assertTrue(t.seen.get("x").tracked);assertFalse(accept(t,quake("x",5.9,"v3"),now+3000,true).get(0).compact);}
 @Test public void disabledOutOfAreaDeepAndStaleTargetsNeverAlert(){AlertTracker t=new AlertTracker();t.accept(List.of(),true,true,now,health,true);assertTrue(accept(t,quake("off",5.4,"v1"),now,false).isEmpty());Alert outside=quake("out",5.4,"v1");outside.targetArea="";assertTrue(accept(t,outside,now,true).isEmpty());Alert deep=quake("deep",5.4,"v1");deep.depth=80;assertTrue(accept(t,deep,now,true).isEmpty());assertTrue(accept(t,quake("stale",5.4,"v1"),now+31*60000,true).isEmpty());}
 @Test public void enablingTargetsNeverReplaysTheExistingSnapshot(){AlertTracker t=new AlertTracker();t.earthquakeReady=true;t.readyCatalogs.add("USGS");t.targetsReady=false;assertTrue(accept(t,quake("existing",5.4,"v1"),now,true).isEmpty());assertTrue(accept(t,quake("new",5.4,"v1"),now+1000,true).get(0).compact);}
 @Test public void aliasAndSourceChangesKeepOneEventAndBrazilRemainsPrimary(){AlertTracker t=new AlertTracker();t.accept(List.of(),true,true,now,health,true);accept(t,quake("USGS:a",5.4,"v1"),now,true);Alert other=quake("USGS:b",5.4,"v1");other.aliases.add("USGS:a");assertTrue(accept(t,other,now+1000,true).isEmpty());Alert br=new Alert("BR:x","earthquake","v1","Brasil","","earthquake",now,now,true);br.provider="USGS";br.catalog="USGS";br.magnitude=2;assertFalse(accept(t,br,now+2000,true).get(0).compact);}
 @Test public void targetQueueIsBoundedDeduplicatedAndPrimaryPromotionRemovesItsCard(){TargetNoticeQueue q=new TargetNoticeQueue();for(int i=0;i<8;i++)q.add(quake("x"+i,5.4,"v1"));q.add(quake("x7",5.5,"v2"));q.primary(List.of(quake("x6",6,"v3")));List<String> ids=new ArrayList<>();Alert a;while((a=q.next(now))!=null)ids.add(a.id);assertEquals(List.of("x4","x5","x7"),ids);q.add(quake("stale",5.4,"v1"));assertNull(q.next(now+31*60000));}
}
